const headers = $input.item.json.headers || {};
const authSecret = headers['x-dispatch-secret'] || (headers['authorization'] || '').replace(/^Bearer\s+/, '');
const expectedSecret = $env.N8N_WEBHOOK_SECRET || 'dev_secret_dispatch_2026';

if (authSecret !== expectedSecret) {
  return [{
    json: {
      authenticated: false,
      error: {
        code: 'UNAUTHORIZED',
        message: 'Invalid or missing x-dispatch-secret authentication header',
        retryable: false
      },
      correlationId: headers['x-correlation-id'] || `corr_${Date.now()}`
    }
  }];
}

const body = $input.item.json.body || {};
const { serviceType, serviceZone, date, preferredWindow } = body;

if (!serviceType || !['HVAC', 'PLUMBING'].includes(serviceType)) {
  return [{
    json: {
      authenticated: true,
      valid: false,
      error: {
        code: 'INVALID_INPUT',
        message: 'serviceType must be either HVAC or PLUMBING',
        retryable: false
      },
      correlationId: headers['x-correlation-id'] || `corr_${Date.now()}`
    }
  }];
}

if (!serviceZone || typeof serviceZone !== 'string') {
  return [{
    json: {
      authenticated: true,
      valid: false,
      error: {
        code: 'INVALID_INPUT',
        message: 'serviceZone is required',
        retryable: false
      },
      correlationId: headers['x-correlation-id'] || `corr_${Date.now()}`
    }
  }];
}

if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  return [{
    json: {
      authenticated: true,
      valid: false,
      error: {
        code: 'INVALID_INPUT',
        message: 'date must be in YYYY-MM-DD format',
        retryable: false
      },
      correlationId: headers['x-correlation-id'] || `corr_${Date.now()}`
    }
  }];
}

return [{
  json: {
    authenticated: true,
    valid: true,
    payload: { serviceType, serviceZone, date, preferredWindow },
    correlationId: headers['x-correlation-id'] || `corr_${Date.now()}`
  }
}];
